describe('Timeout Error Handling', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application
    });

    it('should display a timeout error message when the request takes longer than 10 seconds', () => {
        cy.intercept('GET', '/api/data', (req) => {
            req.reply((res) => {
                // Simulate a delay of 12 seconds
                res.delay(12000).send({ data: 'some data' });
            });
        }).as('getData');

        cy.get('button#fetchData').click(); // Adjust selector to trigger the request
        cy.wait('@getData', { timeout: 15000 }); // Wait for the request to complete

        cy.get('.error-message').should('be.visible').and('contain', 'Request timed out'); // Adjust selector for error message
    });

    it('should not display a timeout error message when the request completes within 10 seconds', () => {
        cy.intercept('GET', '/api/data', (req) => {
            req.reply(200, { data: 'some data' });
        }).as('getData');

        cy.get('button#fetchData').click(); // Adjust selector to trigger the request
        cy.wait('@getData', { timeout: 10000 }); // Wait for the request to complete

        cy.get('.error-message').should('not.exist'); // Ensure no error message is displayed
        cy.get('.data-display').should('be.visible').and('contain', 'some data'); // Adjust selector for data display
    });
});
